import{_ as o,o as a,c as d,a3 as t}from"./chunks/framework.CagObDTx.js";const m=JSON.parse('{"title":"Macros and knobs","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/macros.md","filePath":"developers/commands/macros.md"}'),s={name:"developers/commands/macros.md"};function c(n,e,i,r,h,p){return a(),d("div",null,[...e[0]||(e[0]=[t(`<h1 id="macros-and-knobs" tabindex="-1">Macros and knobs <a class="header-anchor" href="#macros-and-knobs" aria-label="Permalink to &quot;Macros and knobs&quot;">​</a></h1><p>Each of the 32 knobs has four <a href="/versions/cli/v2.0.0/macros/">macros</a>. A macro turns knob motion into MIDI, a rack device parameter or an S32 LFO parameter.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mode=cc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msb=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">74</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> potname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> potname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Cutoff</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobmap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knobmap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span></code></pre></div><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>mode=</code></th><th>Also</th><th>Sends</th><th>Page</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>off</code></td><td>Nothing</td><td><a href="/versions/cli/v2.0.0/macros/disabled">Disabled</a></td></tr><tr><td><code>cc</code></td><td><code>control-change</code></td><td>Control Change</td><td><a href="/versions/cli/v2.0.0/macros/control-change">Control Change</a></td></tr><tr><td><code>pc</code></td><td><code>program-change</code></td><td>Program Change</td><td><a href="/versions/cli/v2.0.0/macros/program-change">Program Change</a></td></tr><tr><td><code>cc14</code></td><td><code>fourteen-bit</code></td><td>14-bit Control Change</td><td><a href="/versions/cli/v2.0.0/macros/fourteen-bit-cc">14-bit CC</a></td></tr><tr><td><code>aftertouch</code></td><td><code>at</code></td><td>Channel aftertouch</td><td><a href="/versions/cli/v2.0.0/macros/channel-aftertouch">Channel aftertouch</a></td></tr><tr><td><code>poly-aftertouch</code></td><td><code>poly-at</code>, <code>pat</code></td><td>Poly aftertouch (<code>msb</code> is the note)</td><td><a href="/versions/cli/v2.0.0/macros/poly-aftertouch">Poly aftertouch</a></td></tr><tr><td><code>nrpn</code></td><td></td><td>NRPN</td><td><a href="/versions/cli/v2.0.0/macros/nrpn">NRPN</a></td></tr><tr><td><code>rpn</code></td><td></td><td>RPN</td><td><a href="/versions/cli/v2.0.0/macros/rpn">RPN</a></td></tr><tr><td><code>pitch-bend</code></td><td><code>pb</code></td><td>Pitch bend</td><td><a href="/versions/cli/v2.0.0/macros/pitch-bend">Pitch bend</a></td></tr><tr><td><code>sysex</code></td><td></td><td>SysEx</td><td><a href="/versions/cli/v2.0.0/macros/sysex">SysEx</a></td></tr><tr><td><code>device</code></td><td><code>device-parameter</code></td><td>A rack device parameter</td><td><a href="/versions/cli/v2.0.0/macros/device-parameter">Device parameter</a></td></tr><tr><td><code>rack</code></td><td><code>rack-parameter</code></td><td>A rack&#39;s BYPASS</td><td><a href="/versions/cli/v2.0.0/macros/rack-control">Rack Control</a></td></tr><tr><td><code>s32-lfo</code></td><td><code>lfo</code></td><td>An S32 LFO parameter</td><td><a href="/versions/cli/v2.0.0/macros/s32-lfo-parameter">S32 LFO</a></td></tr></tbody></table><h2 id="macro-get-macro-set" tabindex="-1"><code>macro get</code> / <code>macro set</code> <a class="header-anchor" href="#macro-get-macro-set" aria-label="Permalink to &quot;\`macro get\` / \`macro set\`&quot;">​</a></h2><p><code>macro get KNOB MACRO</code>: knob <code>1</code>–<code>32</code>, macro <code>1</code>–<code>4</code>.</p><p><code>macro set KNOB MACRO key=value …</code> changes only the keys you name:</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th></tr></thead><tbody><tr><td><code>mode</code></td><td>A name from the table above</td></tr><tr><td><code>msb</code></td><td>CC number, program number, NRPN/RPN MSB, note, …</td></tr><tr><td><code>lsb</code></td><td>LSB, where the mode has one</td></tr><tr><td><code>channel</code></td><td><code>global</code> or <code>1</code>–<code>16</code></td></tr><tr><td><code>min</code> / <code>max</code></td><td>Range. 7-bit modes: <code>0</code>–<code>127</code>. <code>cc14</code>, <code>nrpn</code>, <code>rpn</code>, <code>pitch-bend</code>, <code>sysex</code>: <code>0</code>–<code>16383</code>. <code>mode=rack</code> and <code>target=rack-bypass</code>: <code>0</code>–<code>1</code>. <code>target=snapshot-slot</code>: <code>1</code>–<code>32</code>. <code>target=morph-amount</code>: <code>0</code>–<code>16383</code>. <code>mode=s32-lfo</code>: the setting&#39;s range (<code>enabled</code>, <code>sync</code>, <code>rate</code>, <code>depth</code> <code>0</code>–<code>1</code>; <code>wave</code> <code>1</code>–<code>17</code>; <code>phase</code> <code>0</code>–<code>360</code>; <code>offset</code> <code>-1</code>–<code>1</code>). <code>mode=device</code>: the parameter&#39;s range, except a time that changes with SYNC (see below)</td></tr><tr><td><code>invert</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>outputs</code></td><td><code>none</code>, <code>usb</code>, <code>out1</code>, <code>out2</code>, or a <code>+</code> mix such as <code>usb+out1</code></td></tr><tr><td><code>pickup</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>in</code></td><td>IN SNAPSHOT, <code>yes</code> / <code>no</code></td></tr><tr><td><code>rack</code> / <code>device</code> / <code>param</code></td><td><code>mode=device</code>: rack and device ids from <code>rack list</code> / <code>device list</code>, and a parameter name (<code>bypass</code>, <code>rate</code>, <code>gate</code>, …) or number from <code>schema</code>. <code>mode=rack</code>: the rack id from <code>rack list</code>; without <code>rack=</code> no rack is set. <code>param</code> can only be <code>bypass</code></td></tr><tr><td><code>sub</code></td><td><code>mode=device</code> on a Step Seq step: the step, <code>1</code>–<code>16</code>, or <code>none</code></td></tr><tr><td><code>lfo</code> / <code>lfoParam</code></td><td><code>mode=s32-lfo</code>: the LFO (<code>1</code>–<code>16</code>, or <code>none</code>) and its setting (<code>enabled</code>, <code>wave</code>, <code>rate</code>, <code>sync</code>, <code>phase</code>, <code>depth</code>, <code>offset</code>)</td></tr><tr><td><code>name</code></td><td>The label for a named control</td></tr></tbody></table><p>A rack, device or parameter that is not in the project exits <code>4</code> (<code>NotFound</code>) and changes nothing. Use the ids from <code>rack list</code> / <code>device list</code>, not positions, and a parameter that device has in <code>schema</code>.</p><p>On a time that changes with SYNC (Delay <code>delay-time</code>, Arpeggiator <code>rate</code>, Envelope <code>attack</code> / <code>hold</code> / <code>decay</code> / <code>release</code>), <code>min</code> and <code>max</code> are positions from <code>0</code> to <code>1</code> of the range it has in its current mode: <code>min=0 max=1</code> is the whole range on SYNCED and on FREE, and <code>min=0.5 max=1</code> stays the upper half when SYNC changes. <code>macro get</code> prints the positions. A value above <code>1</code> is read in the current unit (ticks or ms) and stored as its position.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>macro set 5 2 mode=cc msb=74 channel=3 outputs=usb+out1</span></span>
<span class="line"><span>macro set 1 3 mode=cc14 msb=1 lsb=33 channel=3</span></span>
<span class="line"><span>macro set 1 1 mode=device rack=100 device=1000 param=bypass</span></span>
<span class="line"><span>macro set 3 1 mode=s32-lfo lfo=1 lfoParam=depth</span></span>
<span class="line"><span>macro set 4 1 mode=disabled</span></span></code></pre></div><p>Changing the mode, or picking a new target, without <code>min=</code>/<code>max=</code> gives the macro the full range of the new mode, as the panel does. A custom window such as CC <code>10</code>–<code>20</code> is dropped on <code>mode=pc</code> (<code>0</code>–<code>127</code>), <code>mode=cc14</code> (<code>0</code>–<code>16383</code>) or <code>mode=rack</code> (<code>0</code>–<code>1</code>). These keys also reset the range: <code>param=</code> in <code>mode=device</code> (the parameter&#39;s range), <code>lfoParam=</code> in an LFO mode (that setting&#39;s range), <code>rack=</code> in <code>mode=rack</code> (<code>0</code>–<code>1</code>), and <code>part=</code> with <code>target=snapshot-slot</code> / <code>target=morph-amount</code>. Naming the value the macro already has changes nothing.</p><p>These keys keep the window: <code>sub</code>, <code>rack</code> / <code>device</code> in <code>mode=device</code>, <code>channel</code>, <code>msb</code>, <code>lsb</code>, <code>invert</code>, <code>outputs</code>, <code>pickup</code>, <code>in</code>, <code>name</code>. In an LFO mode, an <code>lfo=</code> that changes the LFO index sets the LFO setting to <code>enabled</code> and its range <code>0</code>–<code>1</code>; with <code>lfoParam=</code>, the setting you name decides. Naming the LFO index the macro already has changes nothing, and <code>lfo=none</code> (no LFO) keeps the window and the setting.</p><p>Entering <code>mode=device</code> without <code>param=</code>:</p><ul><li>A macro that already holds a complete device target (a rack, a device and a parameter, <code>bypass</code> included) keeps it, and the S32 gives it that parameter&#39;s range.</li><li>Any other macro (a fresh one, a Rack control, a snapshot or morph macro) leaves the target unset, with the range <code>0</code>–<code>127</code>. Name <code>rack=</code>, <code>device=</code> and <code>param=</code> to target a parameter.</li></ul><p>Entering <code>mode=s32-lfo</code> without <code>lfoParam=</code> keeps the macro&#39;s LFO setting (<code>frequency</code> becomes <code>rate</code>, <code>amplitude</code> becomes <code>depth</code>, any setting an S32 LFO cannot target becomes <code>enabled</code>) with that setting&#39;s range.</p><p>Entering <code>mode=rack</code> drops a device target. With <code>rack=</code>, the knob controls that rack&#39;s BYPASS. Without it, no rack is set until you name one, as on the panel. The range is <code>0</code>–<code>1</code>. <code>device</code>, <code>sub</code>, <code>cv</code>, <code>lfo</code> and <code>lfoParam</code> are refused with <code>mode=rack</code>.</p><p>Name both <code>min=</code> and <code>max=</code> to set your own window on the same line. Naming one takes the other end from the new range (<code>mode=pc min=5</code> gives <code>5</code>–<code>127</code>). The exception is a device parameter, whose range only the S32 knows: there, naming one of the two exits <code>2</code> (<code>name both min= and max=, or neither, when the device parameter changes</code>) and changes nothing. <code>--dry-run</code> shows the range the line would set, <code>parameter-range</code> for a device parameter.</p><p><code>target=snapshot-slot</code> and <code>target=morph-amount</code> with <code>part=</code> turn a macro into a snapshot picker or a morph knob. See <a href="./snapshots#mapping">Snapshots</a>.</p><p><code>target=rack-bypass rack=ID</code> maps a macro to a rack&#39;s BYPASS, the same target the panel&#39;s rack Options use:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>macro set 4 1 target=rack-bypass rack=100</span></span></code></pre></div><p>A parameter has one mapping: one knob macro or one external MIDI row. Giving a knob or external mapping a <strong>new</strong> target clears the parameter&#39;s other mapping, as on the S32. Editing min/max, the name or the CC number of the same target keeps the other mapping; a rejected command changes nothing. A whole knob map (<code>knobmap copy</code>, an editor <code>KNOBMAP_SET</code>) follows the same rule, so the last slot that writes a parameter wins.</p><h2 id="knob-names" tabindex="-1">Knob names <a class="header-anchor" href="#knob-names" aria-label="Permalink to &quot;Knob names&quot;">​</a></h2><p><code>potname get KNOB</code> and <code>potname set KNOB NAME</code>.</p><h2 id="knob-map" tabindex="-1">Knob map <a class="header-anchor" href="#knob-map" aria-label="Permalink to &quot;Knob map&quot;">​</a></h2><p><code>knobmap get [START]</code> lists knob names and their macros from <code>START</code>.</p><p><code>knobmap copy SRC DST</code> copies one knob&#39;s name and all four macros onto another. Because a parameter has one mapping, mapped parameters <strong>move</strong> to the destination knob: the source knob&#39;s slots become disabled and the destination knob&#39;s slots map them.</p><h2 id="output-after-a-set" tabindex="-1">Output after a set <a class="header-anchor" href="#output-after-a-set" aria-label="Permalink to &quot;Output after a set&quot;">​</a></h2><p><code>macro set</code> and <code>potname set</code> print their confirmation line, then the state the S32 now holds (<a href="./session#a-set-prints-the-state-it-left">A set prints the state it left</a>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ s32 --loopback potname set 5 Cutoff</span></span>
<span class="line"><span>pot 5 renamed</span></span>
<span class="line"><span>pot 5 name=Cutoff</span></span>
<span class="line"><span>$ s32 --loopback macro set 5 2 channel=3</span></span>
<span class="line"><span>macro 5/2 updated</span></span>
<span class="line"><span>pot 5 macro 2: mode=disabled msb=0 lsb=0 channel=3 min=0.000 max=127.000 invert=off outputs=none pickup=off in=yes rack=0 device=0 param=0 sub=none cvOut=none lfo=none lfoParam=none name=</span></span></code></pre></div><p>With <code>--json</code>, <code>macro get</code> and <code>macro set</code> print the same object, keyed by the names <code>macro set</code> takes (<code>mode</code>, <code>msb</code>, <code>channel</code>, <code>outputs</code>, <code>in</code>, <code>lfo</code>, <code>lfoParam</code>, <code>cvOut</code>, ...). <code>target</code> and <code>part</code> are fields: <code>null</code> unless the macro is a snapshot-slot, morph-amount or rack-bypass target. <code>lfoParam</code> is the LFO destination field. <code>knobmap get --json</code> lists the knobs with their first macro.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --loopback</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> macro</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> channel=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> msb=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">74</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span></code></pre></div>`,33)])])}const k=o(s,[["render",c]]);export{m as __pageData,k as default};
